from typing import List

from taf.rfrl.procedures.cloud.setups_teardowns.testing_env import TestingEnv
from taf.rfrl.procedures.resources.python.bts.utils.exceptions import ResultError
from taf.rfrl.procedures.resources.python.test_models.cloud.common import (enter_test_dedicated_state,
                                                                           exit_test_dedicated_state,
                                                                           cleanup_after_test_dedicated_state)


def general_siso_auto_cloud_entering_test_dedicated_state_and_running_nr_downlink(testing_env: TestingEnv,
                                                                                  cells_names: List[str],
                                                                                  beam_pattern_id: List[int],
                                                                                  polarization: str,
                                                                                  power_backoff: int,
                                                                                  p_max: int,
                                                                                  ru_mode: str,
                                                                                  test_model: str,
                                                                                  mimo_rank: str,
                                                                                  code_book_2_ant_ports: int,
                                                                                  i2_code_book_4_ant_ports: int,
                                                                                  i11_code_book_4_ant_ports: int,
                                                                                  i13_code_book_4_ant_ports: int,
                                                                                  start_timeout: int = 90,
                                                                                  stop_timeout: int = 90):
    """
    Based on:
    QC Test ID: 203671
    QC Test Name: [2.0] CB010411_L_Operability_CB007120_B_Entering_Test_Dedicated_State_and_run_NR_Downlink_Via_Web

    Should report to:
    QC Test ID: 70684
    QC Test Name: General_SiSo_Auto_Cloud_Entering_Test_Dedicated_State_And_Running_NR_Downlink

    :param testing_env: testing environment prepared for this test case
    :param cells_names: names of cells for which NR Downlink test (with same set of parameters) should be run;
                        can be taken from "NRCELL ID" field of cell details in DU WebEM;
                        i.e. ['NRCELL-1', 'NRCELL-3']
    :param beam_pattern_id: beam pattern ID to be set before starting NR Downlink test; i.e. [1, 1, 1, 1]
    :param polarization: polarization to be set before starting NR Downlink test; one of the following: 'P_plus45_or_0', 'P_minus45_or_90', 'P_both'
    :param power_backoff: power reduction of 0.1 dB to be set before starting NR Downlink test; from <0, 490> range
    :param p_max: maximum power of cell (in dBm) per TX to be set before starting NR Downlink test; from <0, 60> range
    :param ru_mode: RU mode to be set before starting NR Downlink test; one of the following: 'NR_Only', 'MSR', 'Customize_1'
    :param test_model: test model to be set before starting NR Downlink test;
                       one of the following: 'NR-FR1-TM1.1', 'NR-FR1-TM3.1', 'NR-FR1-TM3.2', 'NR-FR1-TM3.1a', 'NR-FR1-TM1.2',
                                             'NR-FR1-TM2', 'NR-FR1-TM2a', 'NR-FR1-TM3.3'
    :param mimo_rank: MIMO rank to be set before starting NR Downlink test; one of the following: 'Rank1', 'Rank2'
    :param code_book_2_ant_ports: code book index for 2x2 MIMO CL Rank1 and Rank2 to be set before starting NR Downlink test;
                                  from <0, 3> range
    :param i2_code_book_4_ant_ports: i2 code book index for 4 layers MIMO to be set before starting NR Downlink test;
                                     from <0, 3> range;
                                     must be set to 0 if polarization is set to 'P_plus45_or_0'
    :param i11_code_book_4_ant_ports: i11 code book index for 4 layers MIMO to be set before starting NR Downlink test;
                                      from <0, 7> range;
    :param i13_code_book_4_ant_ports: i13 code book index for 4 layers MIMO to be set before starting NR Downlink test;
                                      from <0, 1> range;
                                      must be set to 0 if MIMO rank is set to 'Rank1'
    :param start_timeout: timeout (in seconds) for starting NR Downlink test; defaults to 90
    :param stop_timeout: timeout (in seconds) for stopping NR Downlink test; defaults to 90
    """
    bts = testing_env.btss[0]
    errors = testing_env.errors

    bts.cells.check_if_names_exist(names=cells_names)

    for du in bts.dus:
        enter_test_dedicated_state(du)

        for cell_name in cells_names:
            try:
                _start_nr_downlink_test(du,
                                        cell_name,
                                        beam_pattern_id,
                                        polarization,
                                        power_backoff,
                                        p_max,
                                        ru_mode,
                                        test_model,
                                        mimo_rank,
                                        code_book_2_ant_ports,
                                        i2_code_book_4_ant_ports,
                                        i11_code_book_4_ant_ports,
                                        i13_code_book_4_ant_ports,
                                        start_timeout)
                _stop_nr_downlink_test(du,
                                       cell_name,
                                       stop_timeout)
            except ResultError as exc:
                errors.add_from_exception(exc)

        exit_test_dedicated_state(du)

    errors.check()


def teardown_for_general_siso_auto_cloud_entering_test_dedicated_state_and_running_nr_downlink(testing_env: TestingEnv):
    """
    Teardown for this test case, must be used in [Teardown] of Robot Framework test suite.
    :param testing_env: testing environment prepared for this test case
    """
    bts = testing_env.btss[0]
    errors = testing_env.errors

    for du in bts.dus:
        cleanup_after_test_dedicated_state(du, errors)


def _start_nr_downlink_test(du,
                            cell_name,
                            beam_pattern_id,
                            polarization,
                            power_backoff,
                            p_max,
                            ru_mode,
                            test_model,
                            mimo_rank,
                            code_book_2_ant_ports,
                            i2_code_book_4_ant_ports,
                            i11_code_book_4_ant_ports,
                            i13_code_book_4_ant_ports,
                            timeout):
    for cell in du.cells:
        if cell.name == cell_name:
            du.test_model.start_nr_downlink_test(cell=cell,
                                                 beam_pattern_id=beam_pattern_id,
                                                 polarization=polarization,
                                                 power_backoff=power_backoff,
                                                 p_max=p_max,
                                                 ru_mode=ru_mode,
                                                 test_model=test_model,
                                                 mimo_rank=mimo_rank,
                                                 code_book_2_ant_ports=code_book_2_ant_ports,
                                                 i2_code_book_4_ant_ports=i2_code_book_4_ant_ports,
                                                 i11_code_book_4_ant_ports=i11_code_book_4_ant_ports,
                                                 i13_code_book_4_ant_ports=i13_code_book_4_ant_ports,
                                                 timeout=timeout)


def _stop_nr_downlink_test(du, cell_name, timeout):
    for cell in du.cells:
        if cell.name == cell_name:
            du.test_model.stop_nr_downlink_test(cell=cell,
                                                timeout=timeout)
